```java
package org.apache.flink.api.common;

import org.apache.flink.annotation.Internal;

import java.util.Objects;

/**
 * Encapsulates task-specific information: name, index of subtask, parallelism and attempt number.
 */
@Internal
public final class TaskInfo {

    // Metadata for task context
    private final TaskMetadata metadata;

    private TaskInfo(TaskMetadata metadata) {
        this.metadata = metadata;
    }

    public String getTaskName() {
        return metadata.getTaskName();
    }

    public int getMaxNumberOfParallelSubtasks() {
        return metadata.getMaxNumberOfParallelSubtasks();
    }

    public int getSubtaskIndex() {
        return metadata.getIndexOfSubtask();
    }

    public int getNumberOfParallelSubtasks() {
        return metadata.getNumberOfParallelSubtasks();
    }

    public int getAttemptNumber() {
        return metadata.getAttemptNumber();
    }

    public String getTaskNameWithSubtasks() {
        return TaskNameFormatter.defaultFormatter().format(metadata);
    }

    public String getAllocationIDAsString() {
        return metadata.getAllocationId();
    }

    // Builder for constructing TaskInfo objects
    public static class Builder {
        private String taskName;
        private int maxNumberOfParallelSubtasks;
        private int indexOfSubtask;
        private int numberOfParallelSubtasks;
        private int attemptNumber;
        private String allocationId = "UNKNOWN";

        public Builder setTaskName(String taskName) {
            this.taskName = Objects.requireNonNull(taskName, "Task name must not be null.");
            return this;
        }

        public Builder setMaxNumberOfParallelSubtasks(int maxParallelism) {
            if (maxParallelism < 1) {
                throw new IllegalArgumentException("Max parallelism must be a positive number.");
            }
            this.maxNumberOfParallelSubtasks = maxParallelism;
            return this;
        }

        public Builder setSubtaskIndex(int indexOfSubtask) {
            if (indexOfSubtask < 0) {
                throw new IllegalArgumentException("Subtask index must be non-negative.");
            }
            this.indexOfSubtask = indexOfSubtask;
            return this;
        }

        public Builder setNumberOfParallelSubtasks(int parallelism) {
            if (parallelism < 1) {
                throw new IllegalArgumentException("Parallelism must be a positive number.");
            }
            this.numberOfParallelSubtasks = parallelism;
            return this;
        }

        public Builder setAttemptNumber(int attemptNumber) {
            if (attemptNumber < 0) {
                throw new IllegalArgumentException("Attempt number must be non-negative.");
            }
            this.attemptNumber = attemptNumber;
            return this;
        }

        public Builder setAllocationId(String allocationId) {
            this.allocationId = Objects.requireNonNull(allocationId, "Allocation ID must not be null.");
            return this;
        }

        public TaskInfo build() {
            validate();
            return new TaskInfo(new TaskMetadata(taskName, maxNumberOfParallelSubtasks, indexOfSubtask, numberOfParallelSubtasks, attemptNumber, allocationId));
        }

        private void validate() {
            if (indexOfSubtask >= numberOfParallelSubtasks) {
                throw new IllegalArgumentException("Subtask index must be less than the number of parallel subtasks.");
            }
            if (maxNumberOfParallelSubtasks < numberOfParallelSubtasks) {
                throw new IllegalArgumentException("Max parallelism must be >= number of parallel subtasks.");
            }
        }
    }
}

// Encapsulates metadata properties
class TaskMetadata {
    private final String taskName;
    private final int maxNumberOfParallelSubtasks;
    private final int indexOfSubtask;
    private final int numberOfParallelSubtasks;
    private final int attemptNumber;
    private final String allocationId;

    public TaskMetadata(String taskName, int maxNumberOfParallelSubtasks, int indexOfSubtask, int numberOfParallelSubtasks, int attemptNumber, String allocationId) {
        this.taskName = taskName;
        this.maxNumberOfParallelSubtasks = maxNumberOfParallelSubtasks;
        this.indexOfSubtask = indexOfSubtask;
        this.numberOfParallelSubtasks = numberOfParallelSubtasks;
        this.attemptNumber = attemptNumber;
        this.allocationId = allocationId;
    }

    public String getTaskName() {
        return taskName;
    }

    public int getMaxNumberOfParallelSubtasks() {
        return maxNumberOfParallelSubtasks;
    }

    public int getIndexOfSubtask() {
        return indexOfSubtask;
    }

    public int getNumberOfParallelSubtasks() {
        return numberOfParallelSubtasks;
    }

    public int getAttemptNumber() {
        return attemptNumber;
    }

    public String getAllocationId() {
        return allocationId;
    }
}

// Allows configurable formatting of task names with subtasks
class TaskNameFormatter {
    private static final TaskNameFormatter DEFAULT = new TaskNameFormatter();

    public static TaskNameFormatter defaultFormatter() {
        return DEFAULT;
    }

    public String format(TaskMetadata metadata) {
        return String.format("%s (%d/%d)#%d",
                metadata.getTaskName(),
                metadata.getIndexOfSubtask() + 1,
                metadata.getNumberOfParallelSubtasks(),
                metadata.getAttemptNumber());
    }
}
