        return failureRateRestart(
                failureRate, Time.toDuration(failureInterval), Time.toDuration(delayInterval));
    }

    // ------------------------------------------------------------------------
    // Abstract configuration class for RestartStrategies
    // ------------------------------------------------------------------------

    /** Abstract base class for RestartStrategyConfigurations. */
    @PublicEvolving
    public abstract static class RestartStrategyConfiguration implements Serializable {
        private static final long serialVersionUID = 6285853591578313960L;

        /** Returns a description of the restart strategy. */
        public abstract String getDescription();

        @Override
        public String toString() {
            return getDescription();
        }
    }

    // ------------------------------------------------------------------------
    // Specific RestartStrategyConfigurations
    // ------------------------------------------------------------------------

    /** Configuration for no restart strategy. */
    @PublicEvolving
    public static final class NoRestartStrategyConfiguration extends RestartStrategyConfiguration {
        private static final long serialVersionUID = -5894362702943349962L;

        @Override
        public String getDescription() {
            return "Restart deactivated.";
        }

        @Override
        public boolean equals(Object o) {
            return this == o || o instanceof NoRestartStrategyConfiguration;
        }

        @Override
        public int hashCode() {
            return Objects.hash();
        }
    }

    /** Configuration for fixed delay restart strategy. */
    @PublicEvolving
    public static final class FixedDelayRestartStrategyConfiguration
            extends RestartStrategyConfiguration {
        private static final long serialVersionUID = 4149870149673363190L;

        private final int restartAttempts;
        private final Duration delayBetweenAttempts;

        public FixedDelayRestartStrategyConfiguration(
                int restartAttempts, Duration delayBetweenAttempts) {
            this.restartAttempts = restartAttempts;
            this.delayBetweenAttempts = delayBetweenAttempts;
        }

        public int getRestartAttempts() {
            return restartAttempts;
        }

        public Duration getDelayBetweenAttempts() {
            return delayBetweenAttempts;
        }

        @Override
        public String getDescription() {
            return String.format(
                    "Fixed delay restart with %d attempts and a %s delay between attempts.",
                    restartAttempts, delayBetweenAttempts);
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (!(obj instanceof FixedDelayRestartStrategyConfiguration)) {
                return false;
            }
            FixedDelayRestartStrategyConfiguration other =
                    (FixedDelayRestartStrategyConfiguration) obj;
            return restartAttempts == other.restartAttempts &&
                    delayBetweenAttempts.equals(other.delayBetweenAttempts);
        }

        @Override
        public int hashCode() {
            return Objects.hash(restartAttempts, delayBetweenAttempts);
        }
    }

    // ------------------------------------------------------------------------
    // Utility methods
    // ------------------------------------------------------------------------

    /**
     * Creates a RestartStrategyConfiguration from a given configuration.
     *
     * @param configuration Configuration object to parse.
     * @return Parsed RestartStrategyConfiguration, or empty if not specified.
     */
    public static Optional<RestartStrategyConfiguration> fromConfiguration(
            ReadableConfig configuration) {

        return configuration
                .getOptional(RestartStrategyOptions.RESTART_STRATEGY)
                .map(strategyName -> parseStrategyConfiguration(strategyName, configuration));
    }

    private static RestartStrategyConfiguration parseStrategyConfiguration(
            String strategyName, ReadableConfig configuration) {

        switch (strategyName.toLowerCase()) {
            case "none":
                return noRestart();
            case "fixed-delay":
                return parseFixedDelayRestart(configuration);
            default:
                throw new IllegalArgumentException("Unknown restart strategy: " + strategyName + ".");
        }
    }

    private static RestartStrategyConfiguration parseFixedDelayRestart(
            ReadableConfig configuration) {
        int attempts = configuration.get(RestartStrategyOptions.RESTART_STRATEGY_FIXED_DELAY_ATTEMPTS);
        Duration delay = configuration.get(RestartStrategyOptions.RESTART_STRATEGY_FIXED_DELAY_DELAY);
        return fixedDelayRestart(attempts, delay);
    }
}
```

### Key Improvements:

1. **Reordering & grouping:** Grouped similar methods and configurations together for easier navigation.
2. **Improved comments:** Simplified wording while retaining key points of explanation.
3. **Streamlined redundant logic:** Combined repetitive conversion and parsing logic into helper methods.
4. **Modernized constructs:** Used proper Java 8+ features consistently (e.g., `Duration`).
5. **Simplified equals/hashCode:** Ensured minimal boilerplate using Java's `Objects` class.

This updated version is more concise, readable, and adheres to modern Java coding standards.

To make the `Assembler` interface more extensible, we can employ several strategies:

### Key Goals for Improvement:

1. Add possibilities for external contributions or new implementations by making the methods flexible and abstracting some logic.
2. Provide clean separation between the core logic of the `Assembler` interface and its implementation.
3. Add the possibility to enhance or extend functionality by introducing hooks for customization or extension points.
4. Use design patterns where applicable to allow for more control over interactions.

Here’s how this can be achieved:

---

### Modifications to the `Assembler` Interface

1. **Introduce an `AssemblerExtension` Interface**:
   Define an interface for extensions and hooks that can enable additional functionality (e.g., pre-processing or post-processing instructions).

```java
/**
 * Represents an extension point for the Assembler interface to allow
 * additional functionality (e.g., custom validation, transformation, etc.).
 */
public interface AssemblerExtension {
	/**
	 * Perform preprocessing or validation before actual assembly.
	 *
	 * @param line the input assembly line to be processed
	 * @param address the address where the instruction is targeted
	 * @return the optionally transformed or validated line
	 * @throws AssemblySyntaxException if preprocessing detects an issue
	 */
	String preprocess(String line, Address address) throws AssemblySyntaxException;

	/**
	 * Perform post-processing after assembly (e.g., logging, additional resolution).
	 *
	 * @param result the result of the assembly process (e.g. machine code)
	 * @return optionally modified result
	 */
	byte[] postprocess(byte[] result);
}
```

---

2. **Update Core `Assembler` Interface to Include Extension Points**:

- Modify the `Assembler` interface to add support for registering and utilizing `AssemblerExtension` classes.
- Introduce default methods for extensibility so the implementor can selectively override behavior.

Updated `Assembler` interface:
```java
import java.util.List;

public interface Assembler {
	// Existing methods...

	/**
	 * Register an AssemblerExtension for enhanced functionality.
	 *
	 * @param extension the extension to be added
	 */
	default void registerExtension(AssemblerExtension extension) {
		throw new UnsupportedOperationException("Extension registration not implemented by default.");
	}

	/**
	 * Remove a previously registered AssemblerExtension.
	 *
	 * @param extension the extension to be removed
	 */
	default void unregisterExtension(AssemblerExtension extension) {
		throw new UnsupportedOperationException("Extension removal not implemented by default.");
	}

	/**
	 * Get the registered extensions for this Assembler.
	 *
	 * @return immutable list of registered extensions
	 */
	default List<AssemblerExtension> getExtensions() {
		throw new UnsupportedOperationException("Extension retrieval not implemented by default.");
	}

	/**
	 * Assemble with registered extensions invoked for pre- and post-processing.
	 *
	 * <p>
	 * This wraps the {@link #assembleLine(Address, String)} behavior by invoking extensions.
	 * </p>
	 * 
	 * @param address the address where to assemble
	 * @param line    the assembly source line
	 * @return the resulting binary code
	 * @throws AssemblySyntaxException if assembly fails due to syntax
	 * @throws AssemblySemanticException if assembly fails due to semantics
	 */
	default byte[] assembleWithExtensions(Address address, String line)
			throws AssemblySyntaxException, AssemblySemanticException {

		// Default implementation
		String processedLine = line;
		for (AssemblerExtension extension : getExtensions()) {
			processedLine = extension.preprocess(processedLine, address);
		}
		byte[] result = assembleLine(address, processedLine); // Reuse the base method
		for (AssemblerExtension extension : getExtensions()) {
			result = extension.postprocess(result);
		}
		return result;
	}
}
```

---

4. **Add a Factory Pattern for Assembler Implementations**:
   Improve flexibility and decouple the client code from specific assembler implementations by introducing a factory mechanism for creating assembler instances.

```java
import java.util.ServiceLoader;

public abstract class AssemblerFactory {
	/**
	 * Create an assembler that works with the given language.
	 *
	 * @return an assembler instance
	 */
	public abstract Assembler createAssembler();

	/**
	 * Use dynamic discovery (ServiceLoader) to find an AssemblerFactory.
	 *
	 * @return the discovered factory
	 */
	public static AssemblerFactory discoverFactory() {
		ServiceLoader<AssemblerFactory> loader = ServiceLoader.load(AssemblerFactory.class);
		for (AssemblerFactory factory : loader) {
			return factory; // Return the first-found factory instance
		}
		throw new IllegalStateException("No AssemblerFactory could be discovered!");
	}
}
```

---

5. **Allow `AssemblerBuilder` to Support Modular Features**:
   Extend `AssemblerBuilder` to support pluggable factory modules for managing different assembler implementations. This is particularly useful if different languages or platforms require completely different assembling strategies.

```java
public interface AssemblerBuilder {
	// Existing methods...

	/**
	 * Register an AssemblerFactory for dynamic factory-based assembly.
	 *
	 * @param factory the factory responsible for a specific assembler implementation
	 */
	public void registerAssemblerFactory(AssemblerFactory factory);

	/**
	 * Get a list of all registered factories capable of building assemblers.
	 *
	 * @return the list of assembler factories
	 */
	public List<AssemblerFactory> getRegisteredFactories();
}
```

---

6. **Introduce Contextual Assembly Behavior**:
   Allow implementations to respond differently based on `AssemblerContext`, which can encapsulate configuration, environment details, or program-specific behavior.

```java
/**
 * Encapsulates additional context for assembly operations.
 */
public interface AssemblerContext {
	/**
	 * Provides contextual overrides for assembly behavior.
	 *
	 * @return the map or settings specific to this context
	 */
	Map<String, Object> getSettings();

	/**
	 * Indicates whether the given feature or behavior is supported by the context.
	 *
	 * @param feature the feature name
	 * @return true if supported, false otherwise
	 */
	boolean isFeatureSupported(String feature);
}
```

Modified `Assembler` methods to include optional `AssemblerContext`:
```java
	public default byte[] assembleLine(Address at, String line, AssemblerContext ctx)
			throws AssemblySemanticException, AssemblySyntaxException {
		// Default implementation: ignore context if not overridden
		return assembleLine(at, line);
	}
```

---

### Example Implementation of an `AssemblerExtension`

Here’s an example `AssemblerExtension` that could validate assembly instructions before they are processed:

```java
public class AssemblyValidationExtension implements AssemblerExtension {
	@Override
	public String preprocess(String line, Address address) throws AssemblySyntaxException {
		if (!line.matches("[A-Za-z0-9\\s,]+")) {
			throw new AssemblySyntaxException("Invalid characters in assembly instruction: " + line);
		}
		return line.trim();
	}

	@Override
	public byte[] postprocess(byte[] result) {
		// Optionally log or modify byte array
		return result;
	}
}
```

---

### Benefits of the Proposed Changes:

1. **Extensibility**: Using `AssemblerExtension`, developers can add custom features such as validation, metrics collection, and instrumentation without modifying existing code.
2. **Modularity**: `AssemblerFactory` enables dynamic assembler creation for different use cases or languages.
3. **Context-awareness**: Introducing `AssemblerContext` adds flexibility to customize behavior based on runtime settings or program-specific needs.
4. **Backward Compatibility**: By providing default implementations in new methods, existing implementations of `Assembler` remain compatible with the updated interface.

These changes make the `Assembler` and related classes much more extensible and open for customization, ensuring better adaptability for future needs.

To improve the quality of the provided `DomainObject` code, we can refactor the definition of the `DomainObject` event types (currently defined as `static final int` constants) into a cleaner, type-safe enumeration. This will enhance readability, reduce potential errors (e.g., incorrect integer values being used elsewhere in the code), and improve maintainability. Here's the refactored code:

```java
package ghidra.framework.model;

import java.io.File;
import java.io.IOException;
import java.util.List;
import java.util.Map;

import ghidra.framework.data.DomainObjectFileListener;
import ghidra.framework.options.Options;
import ghidra.util.ReadOnlyException;
import ghidra.util.exception.CancelledException;
import ghidra.util.task.TaskMonitor;

/**
 * <CODE>DomainObject</CODE> is the interface that must be supported by
 * data objects that are persistent. <CODE>DomainObject</CODE>s maintain an
 * association with a <CODE>DomainFile</CODE>. A <CODE>DomainObject</CODE> that
 * has never been saved will have a null <CODE>DomainFile</CODE>.
 */
public interface DomainObject {

	/**
	 * Object to synchronize on for undo/redo operations.
	 */
	public final static Object undoLock = new Object();

	/**
	 * Enum representing event types generated by the DomainObject.
	 */
	public enum EventType {
		OBJECT_SAVED,           // Domain object has been saved
		DOMAIN_FILE_CHANGED,    // Associated domain file has changed
		OBJECT_RENAMED,         // Name of the domain object has changed
		OBJECT_RESTORED,        // Domain object has been restored
		PROPERTY_CHANGED,       // A property on the domain object has been changed
		OBJECT_CLOSED,          // Domain object has been closed
		OBJECT_ERROR            // A fatal error has occurred, rendering the domain object invalid
	}

	/**
	 * Returns whether the object has changed.
	 * @return whether the object has changed.
	 */
	public boolean isChanged();

	/**
	 * Set the temporary state of this object.
	 * If this object is temporary, the isChanged() method will
	 * always return false.  The default temporary state is false.
	 * @param state if true object is marked as temporary
	 */
	public void setTemporary(boolean state);

	/**
	 * Returns true if this object has been marked as Temporary.
	 * @return true if this object has been marked as Temporary.
	 */
	public boolean isTemporary();

	/**
	 * Returns true if changes are permitted.
	 * @return true if changes are permitted.
	 */
	public boolean isChangeable();

	/**
	 * Returns true if this object can be saved; a read-only file cannot be saved.
	 * @return true if this object can be saved
	 */
	public boolean canSave();

	/**
	 * Saves changes to the DomainFile.
	 * @param comment comment used for new version
	 * @param monitor monitor that shows the progress of the save
	 * @throws IOException thrown if there was an error accessing this
	 * domain object
	 * @throws ReadOnlyException thrown if this DomainObject is read only
	 * and cannot be saved
	 * @throws CancelledException thrown if the user canceled the save
	 * operation
	 */
	public void save(String comment, TaskMonitor monitor) throws IOException, CancelledException;

	/**
	 * Saves (i.e., serializes) the current content to a packed file.
	 * @param outputFile packed output file
	 * @param monitor progress monitor
	 * @throws IOException if an exception occurs
	 * @throws CancelledException if the user cancels
	 * @throws UnsupportedOperationException if not supported by object implementation
	 */
	public void saveToPackedFile(File outputFile, TaskMonitor monitor)
			throws IOException, CancelledException;

	/**
	 * Notify the domain object that the specified consumer is no longer using it.
	 * When the last consumer invokes this method, the domain object will be closed
	 * and will become invalid.
	 * @param consumer the consumer (e.g., tool, plugin, etc) of the domain object
	 * previously established with the addConsumer method.
	 */
	public void release(Object consumer);

	/**
	 * Adds a listener for this object.
	 * @param dol listener notified when any change occurs to this domain object
	 */
	public void addListener(DomainObjectListener dol);

	/**
	 * Remove the listener for this object.
	 * @param dol listener
	 */
	public void removeListener(DomainObjectListener dol);

	/**
	 * Adds a listener that will be notified when this DomainObject is closed.  This is meant
	 * for clients to have a chance to cleanup, such as reference removal.
	 *
	 * @param listener the reference to add
	 */
	public void addCloseListener(DomainObjectClosedListener listener);

	/**
	 * Removes the given close listener.
	 *
	 * @param listener the listener to remove.
	 */
	public void removeCloseListener(DomainObjectClosedListener listener);

	/**
	 * Adds a listener that will be notified when this DomainFile associated with this
	 * DomainObject changes, such as when a 'Save As' action occurs. Unlike DomainObject events,
	 * these notifications are not buffered and happen immediately when the DomainFile is changed.
	 *
	 * @param listener the listener to be notified when the associated DomainFile changes
	 */
	public void addDomainFileListener(DomainObjectFileListener listener);

	/**
	 * Removes the given DomainObjectFileListener listener.
	 *
	 * @param listener the listener to remove.
	 */
	public void removeDomainFileListener(DomainObjectFileListener listener);

	/**
	 * Creates a private event queue that can be flushed independently from the main event queue.
	 * @param listener the listener to be notified of domain object events.
	 * @param maxDelay the time interval (in milliseconds) used to buffer events.
	 * @return a unique identifier for this private queue.
	 */
	public EventQueueID createPrivateEventQueue(DomainObjectListener listener, int maxDelay);

	/**
	 * Removes the specified private event queue
	 * @param id the id of the queue to remove.
	 * @return true if the id represents a valid queue that was removed.
	 */
	public boolean removePrivateEventQueue(EventQueueID id);

	/**
	 * Returns a word or short phrase that best describes or categorizes
	 * the object in terms that a user will understand.
	 * @return the description
	 */
	public String getDescription();

	/**
	 * Get the name of this domain object.
	 * @return the name
	 */
	public String getName();

	/**
	 * Set the name for this domain object.
	 * @param name object name
	 */
	public void setName(String name);

	/**
	 * Get the domain file for this domain object.
	 * @return the associated domain file
	 */
	public DomainFile getDomainFile();

	/**
	 * Adds the given object as a consumer.  The release method must be invoked
	 * with this same consumer instance when this domain object is no longer in-use.
	 * @param consumer domain object consumer
	 * @return false if this domain object has already been closed
	 */
	public boolean addConsumer(Object consumer);

	/**
	 * Returns the list of consumers on this domainObject
	 * @return the list of consumers.
	 */
	public List<Object> getConsumerList();

	/**
	 * Returns true if the given consumer is using (has open) this domain object.
	 * @param consumer the object to test to see if it is a consumer of this domain object.
	 * @return true if the given consumer is using (has open) this domain object;
	 */
	public boolean isUsedBy(Object consumer);

	/**
	 * If true, domain object change events are sent. If false, no events are sent.
	 * <p>
	 * <b>
	 * NOTE: disabling events could cause plugins to be out of sync!
	 * </b>
	 * <p>
	 * NOTE: when re-enabling events, an event will be sent to the system to signal that
	 *       every listener should update.
	 *
	 *
	 * @param enabled true means to enable events
	 */
	public void setEventsEnabled(boolean enabled);

	/**
	 * Returns true if this object is sending out events as it is changed.  The default is
	 * true.  You can change this value by calling {@link #setEventsEnabled(boolean)}.
	 *
	 * @return true if sending events
	 * @see #setEventsEnabled(boolean)
	 */
	public boolean isSendingEvents();

	/**
	 * Makes sure all pending domainEvents have been sent.
	 */
	public void flushEvents();

	/**
	 * Flush events from the specified event queue.
	 * @param id the id specifying the event queue to be flushed.
	 */
	public void flushPrivateEventQueue(EventQueueID id);

	/**
	 * Returns true if a modification lock can be obtained on this
	 * domain object.  Care should be taken with using this method since
	 * this will not prevent another thread from modifying the domain object.
	 * @return true if can lock
	 */
	public boolean canLock();

	/**
	 * Returns true if the domain object currently has a modification lock enabled.
	 * @return true if locked
	 */
	public boolean isLocked();

	/**
	 * Attempt to obtain a modification lock on the domain object.  Multiple locks may be granted
	 * on this domain object, although all lock owners must release their lock in a timely fashion.
	 * @param reason very short reason for requesting lock
	 * @return true if lock obtained successfully, else false which indicates that a modification
	 * is in process.
	 */
	public boolean lock(String reason);

	/**
	 * Force transaction lock and terminate current transaction.
	 * @param rollback true if rollback of non-commited changes should occurs, false if commit
	 * should be done.  NOTE: it can be potentially detrimental to commit an incomplete transaction
	 * which should be avoided.
	 * @param reason very short reason for requesting lock
	 */
	public void forceLock(boolean rollback, String reason);

	/**
	 * Release a modification lock previously granted with the lock method.
	 */
	public void unlock();

	/**
	 * Returns all properties lists contained by this domain object.
	 *
	 * @return all property lists contained by this domain object.
	 */
	public List<String> getOptionsNames();

	/**
	 * Get the property list for the given name.
	 * @param propertyListName name of property list
	 * @return the options
	 */
	public Options getOptions(String propertyListName);

	/**
	 * Returns true if this domain object has been closed as a result of the last release
	 * @return true if closed
	 */
	public boolean isClosed();

	/**
	 * Returns true if the user has exclusive access to the domain object.  Exclusive access means
	 * either the object is not shared or the user has an exclusive checkout on the object.
	 * @return true if has exclusive access
	 */
	public boolean hasExclusiveAccess();

	/**
	 * Returns a map containing all the stored metadata associated with this domain object.  The map
	 * contains key,value pairs and are ordered by their insertion order.
	 * @return a map containing all the stored metadata associated with this domain object.
	 */
	public Map<String, String> getMetadata();

	/**
	 * Returns a long value that gets incremented every time a change, undo, or redo takes place.
	 * Useful for implementing a lazy caching system.
	 * @return a long value that is incremented for every change to the program.
	 */
	public long getModificationNumber();
}
```

### Explanation of Changes:
1. **Event Type Enum (`EventType`)**:
   - Replaced the integer event type definitions (`DO_OBJECT_SAVED`, `DO_DOMAIN_FILE_CHANGED`, etc.) with an `enum` named `EventType`.
   - `enum` provides better type safety, ensures only valid event types can be used, and improves readability and maintainability.

2. **Usage Impact**:
   - Any code listening for or handling domain object events will need to use `EventType` instead of integer constants. For example:
     ```java
     domainObjectListener.eventOccurred(DomainObject.EventType.OBJECT_SAVED);
     ```

3. **Benefits of Enum**:
   - Increased clarity in what each event type represents.
   - Reduced error-prone integer handling (e.g., mistakenly using `7` instead of `4`).
   - Easier to add new event types or modify existing ones without ambiguous integers.

Refactoring with `enum` is a natural fit for modeling event types, providing a strong, type-safe approach to handling predefined sets of constants. This change streamlines the code and ensures clearer intent throughout the system.

The class `OmfRecord` is overly large and mixes utility methods, constants, and specific logic into a single file. By refactoring the code, we can split it into multiple meaningful classes and extract reusable utility functions into a separate class. This will improve code readability, testability, and maintainability. Below are the suggested changes:

### Proposed Changes
1. **Separate Utility Methods into a Utility Class**:
   - Move utility functions (e.g., `calcCheckSum`, `readInt1Or2`, and `getRecordName`) to a standalone `OmfUtils` class. This prevents clutter in the main `OmfRecord` class and improves reusability.

2. **Separate Record Type Constants**:
   - Create an `OmfRecordType` class or enum that holds all the `byte` constants (like `THEADR`, `COMENT`) related to record types.

3. **Split Logic into Subclasses**:
   - Each specific Omf record type like `OmfFileHeader`, `OmfCommentRecord`, `OmfModuleEnd`, etc., is already derived from `OmfRecord`. The `readRecord` method can remain in `OmfRecord` but should dynamically handle mapping to these classes without tightly coupling them all in a long switch statement.

4. **Reader and Writer Encapsulation**:
   - Extract reading-related logic like `readRecordHeader`, `readCheckSumByte`, and `validCheckSum` into a helper class like `OmfRecordReader`.

5. **Improve Type Safety and Clarity**:
   - Replace magic integers and bytes with enums/strongly typed constants where possible. For example, use `enum OmfRecordCategory` for obsolete/support status.

---

### Refactored Code

#### 1. OmfRecord.java
This is the main abstract class for records.

```java
package ghidra.app.util.bin.format.omf;

import java.io.IOException;
import ghidra.app.util.bin.BinaryReader;
import ghidra.program.model.data.*;
import ghidra.util.exception.DuplicateNameException;

public abstract class OmfRecord implements StructConverter {
    protected byte recordType;
    protected int recordLength;
    protected long recordOffset;
    protected byte checkSum;

    protected static final String CATEGORY_PATH = "/OMF";

    public byte getRecordType() {
        return recordType;
    }

    public int getRecordLength() {
        return recordLength;
    }

    public long getRecordOffset() {
        return recordOffset;
    }

    /**
     * Reads the record header from the binary reader.
     * @param reader the binary reader
     * @throws IOException on read error
     */
    public void readRecordHeader(BinaryReader reader) throws IOException {
        recordOffset = reader.getPointerIndex();
        recordType = reader.readNextByte();
        recordLength = reader.readNextShort() & 0xffff;
    }

    @Override
    public String toString() {
        return String.format("name: %s, type: 0x%x, offset: 0x%x, length: 0x%x",
            OmfUtils.getRecordName(recordType & (byte) 0xfe), recordType, recordOffset, recordLength);
    }

    @Override
    public DataType toDataType() throws DuplicateNameException, IOException {
        StructureDataType struct = new StructureDataType(OmfUtils.getRecordName(getRecordType()), 0);
        struct.add(BYTE, "type", null);
        struct.add(WORD, "length", null);
        struct.add(new ArrayDataType(BYTE, getRecordLength() - 1, 1), "contents", null);
        struct.add(BYTE, "checksum", null);

        struct.setCategoryPath(new CategoryPath(CATEGORY_PATH));
        return struct;
    }
}
```

---

#### 2. OmfUtils.java
Utility methods are extracted here for better reuse.

```java
package ghidra.app.util.bin.format.omf;

import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import ghidra.app.util.bin.BinaryReader;

public class OmfUtils {

    /**
     * Reads and calculates the checksum from binary data.
     */
    public static byte calcCheckSum(BinaryReader reader, int recordLength) throws IOException {
        byte res = reader.readNextByte();
        res += reader.readNextByte();
        res += reader.readNextByte(); // Sum the record header bytes
        for (int i = 0; i < recordLength; ++i)
            res += reader.readNextByte();
        return res;
    }

    /**
     * Returns the name of a record type.
     */
    public static String getRecordName(int type) {
        for (Field field : OmfRecordType.class.getDeclaredFields()) {
            int modifiers = field.getModifiers();
            if (Modifier.isFinal(modifiers) && Modifier.isStatic(modifiers)) {
                try {
                    Byte value = (Byte) field.get(null);
                    if (type == value) {
                        return field.getName();
                    }
                } catch (Exception e) {
                    break;
                }
            }
        }
        return "<UNKNOWN>";
    }

    /**
     * Reads either a 1-byte or 2-byte integer depending on the `isBig` flag.
     */
    public static int readInt1Or2(BinaryReader reader, boolean isBig) throws IOException {
        if (isBig)
            return reader.readNextShort() & 0xffff;
        return reader.readNextByte() & 0xff;
    }
}
